PROGRAM ST190_SORTERING
VAR
    aBesked : ARRAY[0..15] OF BOOL;
    iHead   : INT;
    tmrPush : TON;
END_VAR

ST190_CNV_RUN := EMG_OK AND AIR_OK;

IF ST190_PEC_PART AND NOT ST190_PEC_PART_OLD THEN
    aBesked[iHead] := ST190_HGT_HI;
    iHead := (iHead + 1) MOD 16;
END_IF;

tmrPush(IN := NOT aBesked[(iHead + 12) MOD 16], PT := T#400MS);
ST190_PSH_EXT := tmrPush.Q AND ST190_PSH_HOME;
END_PROGRAM
